package com.moviebooking.notification.controller;
import com.moviebooking.notification.dto.NotificationResponse;import com.moviebooking.notification.service.NotificationService;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.springframework.data.domain.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class NotificationControllerTest {@Mock NotificationService service;@InjectMocks NotificationController controller;@Test void retrievesNotifications(){when(service.all(any())).thenReturn(Page.empty());assertTrue(controller.all(0,10).isSuccess());verify(service).all(any());}@Test void marksRead(){NotificationResponse response=NotificationResponse.builder().id(1L).build();when(service.markRead(1L)).thenReturn(response);assertEquals(1L,controller.read(1L).getData().getId());}}
